{
  "findings": [
    {
      "check_id": "AVD-AZU-0011",
      "title": "Storage account uses an insecure TLS version.",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "CRITICAL",
      "explanation": "The storage account is configured to use TLS1_0, which is outdated and has known vulnerabilities. This can expose data to interception or tampering."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account is not using the latest TLS version. Using the latest TLS version ensures stronger encryption and better security."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not explicitly disable blob anonymous access. This could allow unauthorized users to access blob data."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Soft-delete is not enabled for the storage account. Without soft-delete, accidental or malicious deletions of data cannot be recovered."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n\n  blob_properties {\n    versioning_enabled = true\n    delete_retention_policy {\n      days = 7\n    }\n  }\n\n  allow_blob_public_access = false\n}",
  "fix_summary": "Updated the storage account to enforce HTTPS traffic, set the minimum TLS version to TLS1_2, disabled blob anonymous access, and enabled soft-delete with a retention period of 7 days."
}
